function analizarTemperaturas(temperaturas) {
  if (temperaturas.length === 0) {
    return { promedio: null, maxima: null, minima: null };
  }
  let suma = 0;
  let minima = temperaturas[0];
  let maxima = temperaturas[0];
  for (let i = 0; i < temperaturas.length; i++) {
    suma += temperaturas[i];
    if (temperaturas[i] < minima) minima = temperaturas[i];
    if (temperaturas[i] > maxima) maxima = temperaturas[i];
  }
  return { promedio: +(suma / temperaturas.length).toFixed(3), maxima, minima };
}

