function analizarTemperaturas(temperaturas) {
  if (temperaturas.length === 0) {
    return { promedio: null, maxima: null, minima: null };
  }
  const suma = temperaturas.reduce((acc, n) => acc + n, 0);
  return {
    promedio: +(suma / temperaturas.length).toFixed(3),
    maxima: Math.max(...temperaturas),
    minima: Math.min(...temperaturas),
  };
}

